class TransactionService {
    constructor() {
      this.baseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:3000';
      if (!process.env.REACT_APP_API_BASE_URL) {
        console.warn('REACT_APP_API_BASE_URL is missing, using default: http://localhost:3000');
      }
    }

    // Helper method for headers
    getHeaders() {
      const token = localStorage.getItem('token');
      return {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      };
    }

    // Helper method for API calls
    async fetchWithAuth(endpoint, options = {}) {
      try {
        const response = await fetch(`${this.baseUrl}${endpoint}`, {
          ...options,
          headers: this.getHeaders()
        });

        if (!response.ok) {
          const errorData = await response.json();
          console.error('Error response:', errorData);
          throw new Error(errorData.message || ERROR_MESSAGES.SERVER_ERROR);
        }

        return await response.json();
      } catch (error) {
        if (error.message === 'Failed to fetch') {
          throw new Error(ERROR_MESSAGES.NETWORK_ERROR);
        }
        throw error;
      }
    }

    // Get all transactions with filters
    async getTransactions(filters = {}) {
      const queryParams = new URLSearchParams({
        page: filters.page || 1,
        limit: filters.limit || 10,
        status: filters.status || 'all',
        type: filters.type || 'all',
        dateFrom: filters.dateFrom || '',
        dateTo: filters.dateTo || '',
        search: filters.search || ''
      }).toString();

      return this.fetchWithAuth(`${API_ENDPOINTS.GET_TRANSACTIONS}?${queryParams}`);
    }

    // Other methods like getTransactionById, sendMoney, cancelTransaction, etc., remain the same

    // Download transaction receipt
    async downloadReceipt(transactionId) {
      if (!transactionId) {
        throw new Error(ERROR_MESSAGES.INVALID_TRANSACTION);
      }

      try {
        const response = await fetch(
          `${this.baseUrl}${API_ENDPOINTS.GET_TRANSACTION_DETAILS.replace(':id', transactionId)}/receipt`,
          {
            headers: this.getHeaders()
          }
        );

        if (!response.ok) {
          throw new Error(`${ERROR_MESSAGES.DOWNLOAD_FAILED} for transaction ${transactionId}`);
        }

        const blob = await response.blob();
        return {
          blob,
          filename: `transaction-${transactionId}-receipt.pdf`
        };
      } catch (error) {
        throw new Error(`${ERROR_MESSAGES.DOWNLOAD_FAILED} for transaction ${transactionId}`);
      }
    }

    // Report transaction issue
    async reportIssue(transactionId, issueDetails) {
      if (!transactionId || !issueDetails) {
        throw new Error(ERROR_MESSAGES.INVALID_REPORT_DATA);
      }

      return this.fetchWithAuth(
        `${API_ENDPOINTS.GET_TRANSACTION_DETAILS.replace(':id', transactionId)}/report`,
        {
          method: 'POST',
          body: JSON.stringify(issueDetails)
        }
      );
    }

    // Example method: getExchangeRates
    async getExchangeRates(baseCurrency, extraParams = '') {
      return this.fetchWithAuth(`/api/exchange-rates?base=${baseCurrency}${extraParams}`);
    }
  }

  const transactionService = new TransactionService();

  export default transactionService;
